mapper.update:
UPDATE flt08_buy_lockup
   SET flt08_item_cd     = #{req.itemCode},
       flt08_start_date  = CAST(#{req.startDate} AS date),
       flt08_close_date  = CAST(#{req.closeDate,jdbcType=VARCHAR} AS date),
       flt08_lockup_type = #{req.lockupType}
 WHERE flt08_buy_lockup_id = #{req.buyLockupId}
   AND flt08_company_id    = #{companyId}

mapper.delete:
DELETE FROM flt08_buy_lockup
 WHERE flt08_company_id = #{companyId}
   AND flt08_buy_lockup_id IN
#{buyLockupId}
